220: // nextCommittedEnts returns all the available entries for execution.
221: // Entries can be committed even when the local raft instance has not durably
222: // appended them to the local raft log yet. If allowUnstable is true, committed
223: // entries from the unstable log may be returned; otherwise, only entries known
224: // to reside locally on stable storage will be returned.
225: func (l *raftLog) nextCommittedEnts(allowUnstable bool) (ents []pb.Entry) {
226: 	if l.applyingEntsPaused {
227: 		// Entry application outstanding size limit reached.
228: 		return nil
229: 	}
230: 	if l.hasNextOrInProgressSnapshot() {
231: 		// See comment in hasNextCommittedEnts.
232: 		return nil
233: 	}
234: 	lo, hi := l.applying+1, l.maxAppliableIndex(allowUnstable)+1 // [lo, hi)
235: 	if lo >= hi {
236: 		// Nothing to apply.
237: 		return nil
238: 	}
239: 	maxSize := l.maxApplyingEntsSize - l.applyingEntsSize
240: 	if maxSize <= 0 {
241: 		l.logger.Panicf("applying entry size (%d-%d)=%d not positive",
242: 			l.maxApplyingEntsSize, l.applyingEntsSize, maxSize)
243: 	}
244: 	ents, err := l.slice(lo, hi, maxSize)
245: 	if err != nil {
246: 		l.logger.Panicf("unexpected error when getting unapplied entries (%v)", err)
247: 	}
248: 	return ents
