392: func (l *raftLog) term(i uint64) (uint64, error) {
393: 	// Check the unstable log first, even before computing the valid term range,
394: 	// which may need to access stable Storage. If we find the entry's term in
395: 	// the unstable log, we know it was in the valid range.
396: 	if t, ok := l.unstable.maybeTerm(i); ok {
397: 		return t, nil
398: 	}
399: 
400: 	// The valid term range is [firstIndex-1, lastIndex]. Even though the entry at
401: 	// firstIndex-1 is compacted away, its term is available for matching purposes
402: 	// when doing log appends.
403: 	if i+1 < l.firstIndex() {
404: 		return 0, ErrCompacted
405: 	}
406: 	if i > l.lastIndex() {
407: 		return 0, ErrUnavailable
408: 	}
409: 
410: 	t, err := l.storage.Term(i)
411: 	if err == nil {
412: 		return t, nil
413: 	}
414: 	if err == ErrCompacted || err == ErrUnavailable {
415: 		return 0, err
416: 	}
417: 	panic(err) // TODO(bdarnell)
418: }
