183: // Visit invokes the supplied closure for all tracked progresses in stable order.
184: func (p *ProgressTracker) Visit(f func(id uint64, pr *Progress)) {
185: 	n := len(p.Progress)
186: 	// We need to sort the IDs and don't want to allocate since this is hot code.
187: 	// The optimization here mirrors that in `(MajorityConfig).CommittedIndex`,
188: 	// see there for details.
