190: 	var ids []uint64
191: 	if len(sl) >= n {
192: 		ids = sl[:n]
193: 	} else {
194: 		ids = make([]uint64, n)
195: 	}
196: 	for id := range p.Progress {
197: 		n--
198: 		ids[n] = id
