25: // MajorityConfig is a set of IDs that uses majority quorums to make decisions.
26: type MajorityConfig map[uint64]struct{}
27: 
28: func (c MajorityConfig) String() string {
29: 	sl := make([]uint64, 0, len(c))
30: 	for id := range c {
31: 		sl = append(sl, id)
32: 	}
33: 	slices.Sort(sl)
34: 	var buf strings.Builder
35: 	buf.WriteByte('(')
36: 	for i := range sl {
37: 		if i > 0 {
38: 			buf.WriteByte(' ')
