163: // VoteResult takes a mapping of voters to yes/no (true/false) votes and returns
164: // a result indicating whether the vote is pending (i.e. neither a quorum of
165: // yes/no has been reached), won (a quorum of yes has been reached), or lost (a
166: // quorum of no has been reached).
167: func (c MajorityConfig) VoteResult(votes map[uint64]bool) VoteResult {
168: 	if len(c) == 0 {
169: 		// By convention, the elections on an empty config win. This comes in
170: 		// handy with joint quorums because it'll make a half-populated joint
171: 		// quorum behave like a majority quorum.
172: 		return VoteWon
173: 	}
