175: 	var votedCnt int //vote counts for yes.
176: 	var missing int
177: 	for id := range c {
178: 		v, ok := votes[id]
179: 		if !ok {
180: 			missing++
181: 			continue
182: 		}
183: 		if v {
184: 			votedCnt++
